def parse_int_arg(name: str, default: int, *, minimum: int = 0, maximum: int = 1000) -> int:
    raw = request.args.get(name, str(default))
    try:
        value = int(raw)
    except (TypeError, ValueError) as exc:
        raise NextApiError(f"Invalid integer value for {name}", 400) from exc
    return min(max(value, minimum), maximum)


def parse_uuid(value: Any, field_name: str) -> UUID | None:
    if value in (None, ""):
        return None
    try:
        return UUID(str(value))
    except ValueError as exc:
        raise NextApiError(f"Invalid UUID for {field_name}", 400) from exc


def parse_bool_value(value: Any, *, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "on"}:
        return True
    if text in {"0", "false", "no", "off"}:
        return False
    return default


def normalize_media_group_member_role(value: Any) -> str:
    role = str(value or "member").strip().lower().replace(" ", "_")
    if role not in MEDIA_GROUP_MEMBER_ROLES:
        raise NextApiError("Invalid media group role", 400)
    return role


def can_manage_media_group_members(conn, group_id: UUID, actor: dict[str, Any]) -> bool:
    if actor.get("role") in {"owner", "admin"}:
        return True
    actor_id = actor.get("id")
    if not actor_id:
        return True
    if not table_exists(conn, "media_group_members"):
        return False
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT role
            FROM media_group_members
            WHERE group_id=%s AND user_id=%s
            """,
            (group_id, actor_id),
        )
        member = cur.fetchone()
    return bool(member and member.get("role") in {"owner", "manager"})


def parse_uuid_list(values: Any, field_name: str, *, maximum: int = 250) -> list[UUID]:
    if values in (None, ""):
        return []
    if not isinstance(values, list):
        raise NextApiError(f"{field_name} must be an array", 400)
    if len(values) > maximum:
        raise NextApiError(f"At most {maximum} {field_name} values are allowed", 400)
    parsed: list[UUID] = []
    seen: set[UUID] = set()
    for value in values:
        item = parse_uuid(value, field_name)
        if not item:
            raise NextApiError(f"{field_name} must not contain empty values", 400)
        if item not in seen:
            parsed.append(item)
            seen.add(item)
    return parsed


def require_existing_movie_ids(conn, movie_ids: list[UUID]) -> None:
    if not movie_ids:
        return
    if not table_exists(conn, "movies"):
        raise NextApiError("Movie table is not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT id FROM movies WHERE id = ANY(%s)", (movie_ids,))
        found_ids = {row["id"] for row in cur.fetchall()}
    missing = [str(item) for item in movie_ids if item not in found_ids]
    if missing:
        raise NextApiError(f"Movie not found: {', '.join(missing)}", 404)


def container_type_for_id(conn, container_id: UUID) -> str:
    if not table_exists(conn, "containers"):
        raise NextApiError("Container table is not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT container_type FROM containers WHERE id=%s", (container_id,))
        row = cur.fetchone()
    if not row:
        raise NextApiError("Container not found", 404)
    return str(row["container_type"] or "")


def container_types_for_ids(conn, container_ids: list[UUID]) -> dict[UUID, str]:
    if not container_ids:
        return {}
    if not table_exists(conn, "containers"):
        raise NextApiError("Container table is not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT id, container_type FROM containers WHERE id = ANY(%s)", (container_ids,))
        rows = cur.fetchall()
    found = {row["id"]: str(row["container_type"] or "") for row in rows}
    missing = [str(item) for item in container_ids if item not in found]
    if missing:
        raise NextApiError(f"Container not found: {', '.join(missing)}", 404)
    return found


def normalize_container_type(value: Any) -> str:
    container_type = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    if container_type not in {"box_set", "collection", "vault"}:
        raise NextApiError("containerType must be box_set, collection or vault", 400)
    return container_type


def container_payload(body: dict[str, Any], *, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    existing = existing or {}
    title = clean_text(body.get("title")) if "title" in body else existing.get("title")
    if not title:
        raise NextApiError("Container title is required", 400)
    if len(title) > 240:
        raise NextApiError("Container title must be 240 characters or fewer", 400)
    description = clean_text(body.get("description")) if "description" in body else existing.get("description")
    if description and len(description) > 2000:
        raise NextApiError("Container description must be 2000 characters or fewer", 400)
    year = clean_text(body.get("year")) if "year" in body else existing.get("year")
    if year and len(year) > 40:
        raise NextApiError("Container year must be 40 characters or fewer", 400)
    barcode = clean_text(body.get("barcode")) if "barcode" in body else existing.get("barcode")
    if barcode and len(barcode) > 160:
        raise NextApiError("Container barcode must be 160 characters or fewer", 400)
    if "badgeLabel" in body or "badge_label" in body:
        badge_label = clean_text(body.get("badgeLabel", body.get("badge_label")))
    else:
        badge_label = existing.get("badge_label")
    if badge_label and len(badge_label) > 80:
        raise NextApiError("Container badge must be 80 characters or fewer", 400)
    metadata = body.get("metadata") if isinstance(body.get("metadata"), dict) else existing.get("metadata") or {}
    return {
        "title": title,
        "description": description,
        "year": year,
        "barcode": barcode,
        "badge_label": badge_label,
        "metadata": metadata,
    }


def container_receiver_payload(existing: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any] | None:
    container_type = clean_text(existing.get("container_type"))
    if container_type != "box_set":
        return None

    def comparable(value: Any) -> str:
        return clean_text(value)

    field_map = {
        "title": "title",
        "barcode": "barcode",
        "year": "year",
        "description": "description",
        "badge_label": "badgeLabel",
    }
    contribution: dict[str, Any] = {}
    changed_fields: list[str] = []
    for source_field, target_field in field_map.items():
        old_value = comparable(existing.get(source_field))
        new_value = comparable(payload.get(source_field))
        if old_value == new_value:
            continue
        if not new_value:
            continue
        contribution[target_field] = new_value
        changed_fields.append(target_field)
    if not contribution:
        return None

    metadata = existing.get("metadata") if isinstance(existing.get("metadata"), dict) else {}
    source_reference = {
        "type": "discvault_box_set",
        "key": str(existing.get("id")),
        "publicId": existing.get("public_id"),
        "barcode": payload.get("barcode"),
        "containerType": container_type,
    }
    movievault_id = clean_text(metadata.get("movievault_id") or metadata.get("movieVaultId") or metadata.get("sourceRef"))
    if movievault_id:
        source_reference["movievaultId"] = movievault_id
    return {
        "entityType": "box_set",
        "identity": str(existing.get("public_id") or existing.get("id")),
        "sourceRef": str(existing.get("public_id") or existing.get("id")),
        "sourceReference": source_reference,
        "payload": contribution,
        "metadata": {
            "containerId": str(existing.get("id")),
            "containerType": container_type,
            "changedFields": changed_fields,
            "sourceProviders": ["discvault_local_edit"],
            "acceptedFields": [
                {
                    "pluginId": "discvault_local_edit",
                    "sourceLabel": "DiscVault local edit",
                    "fields": changed_fields,
                }
            ],
        },
    }


def actor_can_delete_movie(actor: dict[str, Any], movie: dict[str, Any]) -> bool:
    role = str(actor.get("role") or "")
    permissions = {str(item) for item in actor.get("permissions") or []}
    if role == "owner" or "*" in permissions or "collection.delete_all" in permissions:
        return True
    if "collection.delete_own" not in permissions:
        return False
    actor_id = actor.get("id")
    owner_id = movie.get("owner_id")
    return bool(actor_id and owner_id and str(actor_id) == str(owner_id))


def delete_movie_records(conn, movie_id: UUID) -> tuple[dict[str, Any], dict[str, int]]:
    existing = movie_entity(conn, movie_id)
    if not existing:
        raise NextApiError("Movie not found", 404)
    deleted: dict[str, int] = {}
    with conn.cursor() as cur:
        if table_exists(conn, "entity_media"):
            cur.execute("DELETE FROM entity_media WHERE entity_type='movie' AND entity_id=%s", (movie_id,))
            deleted["entity_media"] = max(int(cur.rowcount or 0), 0)
        if table_exists(conn, "metadata_field_provenance"):
            cur.execute("DELETE FROM metadata_field_provenance WHERE entity_type='movie' AND entity_id=%s", (movie_id,))
            deleted["metadata_field_provenance"] = max(int(cur.rowcount or 0), 0)
        if table_exists(conn, "collection_items"):
            cur.execute("DELETE FROM collection_items WHERE item_type='movie' AND item_id=%s", (movie_id,))
            deleted["collection_items"] = max(int(cur.rowcount or 0), 0)
        if table_exists(conn, "digital_media_items"):
            cur.execute("UPDATE digital_media_items SET matched_movie_id=NULL, updated_at=now() WHERE matched_movie_id=%s", (movie_id,))
            deleted["digital_media_items_unmatched"] = max(int(cur.rowcount or 0), 0)
        if table_exists(conn, "containers"):
            cur.execute("UPDATE containers SET primary_movie_id=NULL, updated_at=now() WHERE primary_movie_id=%s", (movie_id,))
            deleted["container_primary_refs"] = max(int(cur.rowcount or 0), 0)
        cur.execute("DELETE FROM movies WHERE id=%s", (movie_id,))
        deleted["movies"] = max(int(cur.rowcount or 0), 0)
    return existing, deleted


def delete_container_records(conn, container_id: UUID) -> tuple[dict[str, Any], dict[str, int]]:
    existing = container_entity(conn, container_id)
    if not existing:
        raise NextApiError("Container not found", 404)
    deleted: dict[str, int] = {}
    with conn.cursor() as cur:
        if table_exists(conn, "collection_items"):
            cur.execute(
                "DELETE FROM collection_items WHERE collection_id=%s OR item_id=%s",
                (container_id, container_id),
            )
            deleted["collection_items"] = max(int(cur.rowcount or 0), 0)
        if table_exists(conn, "container_movies"):
            cur.execute("DELETE FROM container_movies WHERE container_id=%s", (container_id,))
            deleted["container_movies"] = max(int(cur.rowcount or 0), 0)
        if table_exists(conn, "container_identifiers"):
            cur.execute("DELETE FROM container_identifiers WHERE container_id=%s", (container_id,))
            deleted["container_identifiers"] = max(int(cur.rowcount or 0), 0)
        if table_exists(conn, "entity_media"):
            cur.execute("DELETE FROM entity_media WHERE entity_type='container' AND entity_id=%s", (container_id,))
            deleted["entity_media"] = max(int(cur.rowcount or 0), 0)
        if table_exists(conn, "metadata_field_provenance"):
            cur.execute("DELETE FROM metadata_field_provenance WHERE entity_type='container' AND entity_id=%s", (container_id,))
            deleted["metadata_field_provenance"] = max(int(cur.rowcount or 0), 0)
        cur.execute("DELETE FROM containers WHERE id=%s", (container_id,))
        deleted["containers"] = max(int(cur.rowcount or 0), 0)
    return existing, deleted


def import_job_persistence_from_result(result: Any) -> dict[str, Any]:
    if not isinstance(result, dict):
        return {}
    persistence = result.get("persistence")
    if isinstance(persistence, dict):
        return persistence
    nested = result.get("result")
    if isinstance(nested, dict) and isinstance(nested.get("persistence"), dict):
        return nested["persistence"]
    return {}


def import_job_is_collection_import(job: dict[str, Any]) -> bool:
    payload = job.get("payload") or {}
    return (
        job.get("job_type") == PLUGIN_EXECUTION_JOB_TYPE
        and clean_text(payload.get("entrypoint")) == "import_source"
    )


def import_rollback_movie_ids(persistence: dict[str, Any]) -> list[UUID]:
    raw_ids = persistence.get("rollbackMovieIds") or persistence.get("rollback_movie_ids")
    if not isinstance(raw_ids, list):
        raw_ids = [
            movie.get("id")
            for movie in persistence.get("movies", [])
            if isinstance(movie, dict) and clean_text(movie.get("action")) == "created"
        ]
    movie_ids: list[UUID] = []
    seen: set[UUID] = set()
    for value in raw_ids:
        try:
            movie_id = UUID(str(value))
        except (TypeError, ValueError):
            continue
        if movie_id not in seen:
            movie_ids.append(movie_id)
            seen.add(movie_id)
    return movie_ids


def import_rollback_container_candidates(persistence: dict[str, Any]) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []
    collection_id = clean_text(persistence.get("collectionId") or persistence.get("collection_id"))
    if collection_id and bool(persistence.get("collectionCreated") or persistence.get("collection_created")):
        candidates.append(
            {
                "id": collection_id,
                "title": "Import collection",
                "containerType": "collection",
                "created": True,
            }
        )
    for container in persistence.get("containers", []):
        if not isinstance(container, dict) or not bool(container.get("created")):
            continue
        candidates.append(container)
    deduped: list[dict[str, Any]] = []
    seen: set[str] = set()
    for candidate in candidates:
        container_id = clean_text(candidate.get("id"))
        if not container_id or container_id in seen:
            continue
        seen.add(container_id)
        deduped.append(candidate)
    return deduped


def import_container_has_members(conn, container_id: UUID, container_type: str) -> bool:
    if container_type == "collection" and table_exists(conn, "collection_items"):
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM collection_items WHERE collection_id=%s LIMIT 1", (container_id,))
            return bool(cur.fetchone())
    if container_type in {"box_set", "vault"} and table_exists(conn, "container_movies"):
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM container_movies WHERE container_id=%s LIMIT 1", (container_id,))
            return bool(cur.fetchone())
    return False


def rollback_import_job_records(
    conn,
    *,
    job_id: UUID,
    actor: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    if not table_exists(conn, "background_jobs"):
        raise NextApiError("Background job table is not available", 503)
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                id,
                job_type,
                status,
                requested_by,
                payload,
                result,
                error,
                created_at,
                started_at,
                finished_at
            FROM background_jobs
            WHERE id=%s
            FOR UPDATE
            """,
            (job_id,),
        )
        row = cur.fetchone()
    if not row or not import_job_is_collection_import(row):
        raise NextApiError("Import job not found", 404)
    if row["status"] != "completed":
        raise NextApiError("Only completed import jobs can be rolled back", 409)
    result = row.get("result") or {}
    if not isinstance(result, dict):
        result = {}
    existing_rollback = result.get("rollback") if isinstance(result.get("rollback"), dict) else {}
    if existing_rollback.get("status") == "completed":
        return job_row(row), existing_rollback
    persistence = import_job_persistence_from_result(result)
    if not persistence:
        raise NextApiError("Import job does not contain rollback metadata", 409)
    movie_ids = import_rollback_movie_ids(persistence)
    container_candidates = import_rollback_container_candidates(persistence)
    deleted_movies: list[dict[str, Any]] = []
    deleted_containers: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    deleted_counts: dict[str, int] = {}
    for movie_id in movie_ids:
        movie = movie_entity(conn, movie_id)
        if not movie:
            skipped.append({"type": "movie", "id": str(movie_id), "reason": "already_missing"})
            continue
        movie, deleted = delete_movie_records(conn, movie_id)
        deleted_movies.append({"id": str(movie_id), "title": movie.get("title"), "deleted": deleted})
        for key, value in deleted.items():
            deleted_counts[key] = deleted_counts.get(key, 0) + int(value or 0)
        revision = next_revision(conn) if table_exists(conn, "sync_state") else 0
        if revision and table_exists(conn, "sync_changes"):
            sync_change(
                conn,
                revision=revision,
                entity_type="movie",
                entity_id=str(movie_id),
                operation="delete",
                payload={
                    "id": str(movie_id),
                    "title": movie.get("title"),
                    "clientId": "next-app",
                    "clientMutationId": f"import-rollback-movie-{uuid.uuid4()}",
                    "actor": actor_job_payload(actor),
                },
            )
    for candidate in container_candidates:
        try:
            container_id = UUID(str(candidate.get("id")))
        except (TypeError, ValueError):
            continue
        container = container_entity(conn, container_id)
        if not container:
            skipped.append({"type": "container", "id": str(container_id), "reason": "already_missing"})
            continue
        container_type = clean_text(container.get("container_type") or candidate.get("containerType"))
        if import_container_has_members(conn, container_id, container_type):
            skipped.append({"type": "container", "id": str(container_id), "title": container.get("title"), "reason": "not_empty"})
            continue
        container, deleted = delete_container_records(conn, container_id)
        deleted_containers.append(
            {
                "id": str(container_id),
                "title": container.get("title"),
                "containerType": container.get("container_type"),
                "deleted": deleted,
            }
        )
        for key, value in deleted.items():
            deleted_counts[key] = deleted_counts.get(key, 0) + int(value or 0)
    rollback = {
        "status": "completed",
        "rolledBackAt": datetime.now().isoformat(),
        "requestedBy": actor_job_payload(actor),
        "deletedMovies": deleted_movies,
        "deletedContainers": deleted_containers,
        "deleted": deleted_counts,
        "skipped": skipped,
        "sourceKind": persistence.get("sourceKind"),
        "sourcePath": persistence.get("sourcePath"),
    }
    result["rollback"] = rollback
    with conn.cursor() as cur:
        cur.execute(
            """
            UPDATE background_jobs
            SET result=%s
            WHERE id=%s
            RETURNING
                id,
                job_type,
                status,
                requested_by,
                payload,
                result,
                error,
                created_at,
                started_at,
                finished_at
            """,
            (Jsonb(json_ready(result)), job_id),
        )
        updated = cur.fetchone()
    audit_event(
        conn,
        event_type="import_source.rollback_completed",
        category="import",
        actor=actor,
        target_type="background_job",
        target_id=job_id,
        summary="Rolled back an import source job",
        metadata={
            "jobId": str(job_id),
            "pluginId": clean_text((row.get("payload") or {}).get("pluginId")),
            "deleted": deleted_counts,
            "skipped": skipped,
        },
    )
    return job_row(updated), rollback


def ensure_sync_state(conn) -> int:
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO sync_state (id, revision)
            VALUES ('global', 0)
            ON CONFLICT (id) DO NOTHING
            """
        )
        cur.execute("SELECT revision FROM sync_state WHERE id='global'")
        row = cur.fetchone()
    return int(row["revision"] if row else 0)


def current_revision(conn) -> int:
    if not table_exists(conn, "sync_state"):
        return 0
    return ensure_sync_state(conn)


def next_revision(conn) -> int:
    with conn.cursor() as cur:
        cur.execute(
            """
            UPDATE sync_state
            SET revision = revision + 1,
                updated_at = now()
            WHERE id='global'
            RETURNING revision
            """
        )
        row = cur.fetchone()
    if not row:
        ensure_sync_state(conn)
        return next_revision(conn)
    return int(row["revision"])


def sync_change(
    conn,
    *,
    revision: int,
    entity_type: str,
    entity_id: str,
    operation: str,
    payload: dict[str, Any],
) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO sync_changes (
                revision,
                entity_type,
                entity_id,
                operation,
                payload
            )
            VALUES (%s, %s, %s, %s, %s)
            """,
            (revision, entity_type, entity_id, operation, Jsonb(json_ready(payload))),
        )


def idempotency_key(client_id: str, client_mutation_id: str) -> str:
    return f"sync:{client_id}:{client_mutation_id}"


def stored_idempotency_response(conn, key: str) -> dict[str, Any] | None:
    with conn.cursor() as cur:
        cur.execute("SELECT response FROM idempotency_records WHERE key=%s", (key,))
        row = cur.fetchone()
    return dict(row["response"]) if row else None


def store_idempotency_response(
    conn,
    *,
    key: str,
    operation: str,
    status: str,
    entity_type: str,
    entity_id: UUID | None,
    response_payload: dict[str, Any],
) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO idempotency_records (
                key,
                operation,
                status,
                entity_type,
                entity_id,
                response
            )
            VALUES (%s, %s, %s, %s, %s, %s)
            ON CONFLICT (key) DO UPDATE SET
                updated_at=now()
            """,
            (key, operation, status, entity_type, entity_id, Jsonb(json_ready(response_payload))),
        )


def app_settings_map(conn) -> dict[str, Any]:
    if not table_exists(conn, "app_settings"):
        return {}
    with conn.cursor() as cur:
        cur.execute("SELECT key, value FROM app_settings WHERE is_secret = false")
        return {row["key"]: row["value"] for row in cur.fetchall()}


def app_setting_value(conn, key: str, default: Any = None, *, include_secret: bool = False) -> Any:
    if not table_exists(conn, "app_settings"):
        return default
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT value
            FROM app_settings
            WHERE key=%s
              AND (%s OR is_secret = false)
            """,
            (key, include_secret),
        )
        row = cur.fetchone()
    return row["value"] if row else default


def set_app_setting_value(conn, key: str, value: Any, *, is_secret: bool = False, actor_id: UUID | str | None = None) -> None:
    if not table_exists(conn, "app_settings"):
        raise NextApiError("App settings table is not available", 503)
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO app_settings (key, value, is_secret, updated_at, updated_by)
            VALUES (%s, %s, %s, now(), %s)
            ON CONFLICT (key) DO UPDATE SET
                value=EXCLUDED.value,
                is_secret=EXCLUDED.is_secret,
                updated_at=now(),
                updated_by=EXCLUDED.updated_by
            """,
            (key, Jsonb(json_ready(value)), is_secret, actor_id),
        )


def push_vapid_subject() -> str:
    return os.environ.get("VAPID_SUBJECT") or os.environ.get("DISCVAULT_VAPID_SUBJECT") or "mailto:no-reply@discvault.app"


def get_or_create_push_vapid_keys(conn) -> tuple[str, str]:
    public_key = app_setting_value(conn, "vapid_public_key", include_secret=False)
    private_key = app_setting_value(conn, "vapid_private_key", include_secret=True)
    if public_key and private_key:
        return str(public_key), str(private_key)
    from cryptography.hazmat.backends import default_backend
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives.serialization import Encoding, PublicFormat

    private = ec.generate_private_key(ec.SECP256R1(), default_backend())
    public_bytes = private.public_key().public_bytes(Encoding.X962, PublicFormat.UncompressedPoint)
    public_key = base64.urlsafe_b64encode(public_bytes).rstrip(b"=").decode("ascii")
    private_raw = private.private_numbers().private_value.to_bytes(32, "big")
    private_key = base64.urlsafe_b64encode(private_raw).rstrip(b"=").decode("ascii")
    set_app_setting_value(conn, "vapid_public_key", public_key, is_secret=False)
    set_app_setting_value(conn, "vapid_private_key", private_key, is_secret=True)
    return public_key, private_key


def notification_preference_map(conn, user_id: UUID | str | None) -> dict[str, bool]:
    values = dict(NOTIFICATION_PREF_DEFAULTS)
    if not user_id or not table_exists(conn, "notification_preferences"):
        return values
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT pref_key, enabled
            FROM notification_preferences
            WHERE user_id=%s
            """,
            (user_id,),
        )
        for row in cur.fetchall():
            if row["pref_key"] in values:
                values[row["pref_key"]] = bool(row["enabled"])
    return values


def notification_counts(conn, user_id: UUID | str | None) -> dict[str, int]:
    if not user_id or not table_exists(conn, "user_notifications"):
        return {"total": 0, "unread": 0}
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                COUNT(*)::int AS total,
                COUNT(*) FILTER (WHERE read_at IS NULL)::int AS unread
            FROM user_notifications
            WHERE user_id=%s
            """,
            (user_id,),
        )
        row = cur.fetchone() or {}
    return {"total": int(row.get("total") or 0), "unread": int(row.get("unread") or 0)}


def user_notification_rows(conn, user_id: UUID | str, limit: int = 100) -> list[dict[str, Any]]:
    if not table_exists(conn, "user_notifications"):
        return []
    limit = min(max(int(limit or 100), 1), 250)
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT id, event_id, title, body, payload, read_at, created_at
            FROM user_notifications
            WHERE user_id=%s
            ORDER BY created_at DESC
            LIMIT %s
            """,
            (user_id, limit),
        )
        return cur.fetchall()


def create_user_notification(
    conn,
    user_id: UUID | str,
    *,
    title: str,
    body: str = "",
    url: str = "/notifications",
    pref_key: str = "app_updates",
    payload: dict[str, Any] | None = None,
    send_push: bool = True,
) -> dict[str, Any]:
    if not table_exists(conn, "user_notifications"):
        raise NextApiError("Notifications table is not available", 503)
    notification_payload = dict(payload or {})
    notification_payload.setdefault("url", url)
    notification_payload.setdefault("prefKey", pref_key)
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO user_notifications (user_id, title, body, payload)
            VALUES (%s, %s, %s, %s)
            RETURNING id, event_id, title, body, payload, read_at, created_at
            """,
            (user_id, title, body, Jsonb(json_ready(notification_payload))),
        )
        notification = cur.fetchone() or {}
    errors: list[str] = []
    if send_push and notification_preference_map(conn, user_id).get(pref_key, True):
        errors = send_push_to_user(conn, user_id, title=title, body=body, url=url)
    notification["pushErrors"] = errors
    return notification


def send_push_to_user(conn, user_id: UUID | str, *, title: str, body: str = "", url: str = "/notifications") -> list[str]:
    if not table_exists(conn, "push_subscriptions"):
        return ["Push subscriptions table is not available"]
    public_key, private_key = get_or_create_push_vapid_keys(conn)
    del public_key
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT id, endpoint, p256dh, auth
            FROM push_subscriptions
            WHERE user_id=%s
            ORDER BY is_primary DESC, updated_at DESC
            """,
            (user_id,),
        )
        subscriptions = cur.fetchall()
    if not subscriptions:
        return ["No push subscription found for this user"]
    try:
        from pywebpush import webpush
    except Exception as exc:
        return [f"pywebpush is not available: {exc}"]
    errors: list[str] = []
    stale_endpoints: list[str] = []
    for subscription in subscriptions:
        endpoint = str(subscription.get("endpoint") or "")
        try:
            headers = None
            if "notify.windows.com" in endpoint or "wns.windows.com" in endpoint:
                headers = {"X-WNS-Type": "wns/raw", "Content-Type": "application/octet-stream"}
            webpush(
                subscription_info={
                    "endpoint": endpoint,
                    "keys": {"p256dh": subscription.get("p256dh"), "auth": subscription.get("auth")},
                },
                data=json_lib.dumps({"title": title, "body": body, "url": url}),
                vapid_private_key=private_key,
                vapid_claims={"sub": push_vapid_subject()},
                ttl=86400,
                headers=headers,
            )
        except Exception as exc:
            status = getattr(getattr(exc, "response", None), "status_code", None)
            errors.append(f"Push failed ({status or 'unknown'}): {exc}")
            if status in {404, 410} and endpoint:
                stale_endpoints.append(endpoint)
    if stale_endpoints:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM push_subscriptions WHERE endpoint = ANY(%s)", (stale_endpoints,))
    return errors


def normalized_app_preference_key(key: Any) -> str:
    text = str(key or "").strip()
    return APP_PREFERENCE_ALIASES.get(text, text)


def validate_app_preference(key: str, value: Any) -> Any:
    key = normalized_app_preference_key(key)
    if key not in APP_PREFERENCE_DEFAULTS:
        raise NextApiError(f"Unknown preference: {key}", 400)
    if key in APP_BOOLEAN_PREFERENCES:
        return parse_bool_value(value, default=bool(APP_PREFERENCE_DEFAULTS[key]))
    if key in APP_CHOICE_PREFERENCES:
        text = str(value or APP_PREFERENCE_DEFAULTS[key]).strip()
        text = text.upper() if key == "rating_country" else text.lower()
        if text not in APP_CHOICE_PREFERENCES[key]:
            raise NextApiError(f"Invalid value for preference {key}", 400)
        return text
    if key == "default_media_group_id":
        text = str(value or "").strip()
        if text:
            parse_uuid(text, "defaultMediaGroupId")
        return text
    return value


def app_global_preferences(conn) -> dict[str, Any]:
    values = dict(APP_PREFERENCE_DEFAULTS)
    settings = app_settings_map(conn)
    for key in APP_PREFERENCE_DEFAULTS:
        if key in settings:
            values[key] = validate_app_preference(key, settings[key])
    if "show_search_button" in settings and "show_collection_search" not in settings:
        values["show_collection_search"] = validate_app_preference("show_collection_search", settings["show_search_button"])
    return values


def app_user_preferences(conn, user_id: UUID | str | None) -> dict[str, Any]:
    if not user_id or not table_exists(conn, "user_preferences"):
        return {}
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT key, value
            FROM user_preferences
            WHERE user_id=%s
            """,
            (user_id,),
        )
        rows = cur.fetchall()
    values: dict[str, Any] = {}
    for row in rows:
        key = normalized_app_preference_key(row["key"])
        if key not in APP_PREFERENCE_DEFAULTS:
            continue
        values[key] = validate_app_preference(key, row["value"])
    return values


def app_effective_preferences(conn, user_id: UUID | str | None = None) -> dict[str, Any]:
    values = app_global_preferences(conn)
    values.update(app_user_preferences(conn, user_id))
    return values


def set_app_user_preferences(conn, user_id: UUID | str, updates: dict[str, Any]) -> dict[str, Any]:
    if not table_exists(conn, "user_preferences"):
        raise NextApiError("User preferences table is not available", 503)
    normalized: dict[str, Any] = {}
    for raw_key, raw_value in updates.items():
        key = normalized_app_preference_key(raw_key)
        normalized[key] = validate_app_preference(key, raw_value)
    with conn.cursor() as cur:
        for key, value in normalized.items():
            cur.execute(
                """
                INSERT INTO user_preferences (user_id, key, value, updated_at)
                VALUES (%s, %s, %s, now())
                ON CONFLICT (user_id, key) DO UPDATE SET
                    value=EXCLUDED.value,
                    updated_at=now()
                """,
                (user_id, key, Jsonb(json_ready(value))),
            )
    return app_effective_preferences(conn, user_id)


def reconcile_legacy_metadata_plugins(conn) -> dict[str, Any] | None:
    if not table_exists(conn, "app_settings") or not table_exists(conn, "metadata_plugins"):
        return None
    settings = app_settings_map(conn)
    if not settings or "legacy_metadata_plugins_reconciled" in settings:
        return None
    legacy_keys = {
        "metadata_source_order",
        "tmdb_enabled",
        "omdb_enabled",
        "movievault_enabled",
        "bluray_scrape_enabled",
        "bluray_com_enabled",
        "upcitemdb_enabled",
    }
    if not any(key in settings for key in legacy_keys):
        return None
    return apply_legacy_metadata_plugin_plan(conn, settings, Jsonb)


def sync_metadata_plugin_registry(conn) -> None:
    sync_plugin_registry(conn, table_exists, Jsonb)
    if reconcile_legacy_metadata_plugins(conn):
        sync_plugin_registry(conn, table_exists, Jsonb)


def next_user_primary_role(conn, user_id: UUID | str) -> str | None:
    if not table_exists(conn, "user_roles") or not table_exists(conn, "roles"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT r.key
            FROM user_roles ur
            JOIN roles r ON r.id = ur.role_id
            WHERE ur.user_id=%s
            ORDER BY
                CASE r.key
                    WHEN 'owner' THEN 0
                    WHEN 'admin' THEN 1
                    ELSE 2
                END,
                r.key
            LIMIT 1
            """,
            (user_id,),
        )
        row = cur.fetchone()
    return row["key"] if row else None


def next_profile_user_payload(conn, user: dict[str, Any]) -> dict[str, Any]:
    user_id = user["id"]
    avatar: dict[str, Any] | None = None
    fresh_user = user
    if table_exists(conn, "users"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    u.id,
                    u.username,
                    u.display_name,
                    u.first_name,
                    u.last_name,
                    u.status,
                    u.avatar_asset_id,
                    u.updated_at,
                    ma.id AS avatar_id,
                    ma.kind AS avatar_kind,
                    ma.variant AS avatar_variant,
                    ma.storage_backend AS avatar_storage_backend,
                    ma.storage_key AS avatar_storage_key,
                    ma.source_url AS avatar_source_url,
                    ma.provider_id AS avatar_provider_id,
                    ma.content_type AS avatar_content_type,
                    ma.width AS avatar_width,
                    ma.height AS avatar_height,
                    ma.size_bytes AS avatar_size_bytes,
                    ma.sha256 AS avatar_sha256,
                    ma.metadata AS avatar_metadata,
                    ma.created_at AS avatar_created_at
                FROM users u
                LEFT JOIN media_assets ma ON ma.id = u.avatar_asset_id
                WHERE u.id=%s
                """,
                (user_id,),
            )
            row = cur.fetchone()
        if row:
            fresh_user = row
            if row.get("avatar_id"):
                avatar = {
                    "id": row.get("avatar_id"),
                    "kind": row.get("avatar_kind"),
                    "variant": row.get("avatar_variant"),
                    "storage_backend": row.get("avatar_storage_backend"),
                    "storage_key": row.get("avatar_storage_key"),
                    "source_url": row.get("avatar_source_url"),
                    "provider_id": row.get("avatar_provider_id"),
                    "content_type": row.get("avatar_content_type"),
                    "width": row.get("avatar_width"),
                    "height": row.get("avatar_height"),
                    "size_bytes": row.get("avatar_size_bytes"),
                    "sha256": row.get("avatar_sha256"),
                    "metadata": row.get("avatar_metadata"),
                    "created_at": row.get("avatar_created_at"),
                }
    avatar_url = media_asset_public_url(avatar)
    display_name = fresh_user.get("display_name") or fresh_user.get("username")
    return {
        "id": fresh_user.get("id"),
        "username": fresh_user.get("username"),
        "displayName": display_name,
        "display_name": display_name,
        "first_name": fresh_user.get("first_name"),
        "last_name": fresh_user.get("last_name"),
        "role": fresh_user.get("role") or next_user_primary_role(conn, user_id),
        "avatarAssetId": fresh_user.get("avatar_asset_id"),
        "avatar_asset_id": fresh_user.get("avatar_asset_id"),
        "avatarUrl": avatar_url,
        "avatar_url": avatar_url,
        "updated_at": fresh_user.get("updated_at"),
    }


def next_profile_recovery_payload(conn, user_id: UUID | str) -> dict[str, Any]:
    if not table_exists(conn, "recovery_codes"):
        return {
            "available": False,
            "activeCount": 0,
            "usedCount": 0,
            "lastGeneratedAt": None,
        }
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                COUNT(*) FILTER (
                    WHERE used_at IS NULL
                      AND (expires_at IS NULL OR expires_at > now())
                )::int AS active_count,
                COUNT(*) FILTER (WHERE used_at IS NOT NULL)::int AS used_count,
                MAX(created_at) AS last_generated_at
            FROM recovery_codes
            WHERE user_id=%s
            """,
            (user_id,),
        )
        row = cur.fetchone() or {}
    return {
        "available": True,
        "activeCount": int(row.get("active_count") or 0),
        "usedCount": int(row.get("used_count") or 0),
        "lastGeneratedAt": row.get("last_generated_at"),
    }


def permission_key_catalog(conn) -> set[str]:
    if not table_exists(conn, "permissions"):
        return set()
    with conn.cursor() as cur:
        cur.execute("SELECT key FROM permissions")
        return {str(row["key"]) for row in cur.fetchall()}


def api_access_token_row(row: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": row.get("id"),
        "name": row.get("name"),
        "scopes": row.get("scopes") or [],
        "permissionKeys": row.get("permission_keys") or row.get("permissionKeys") or [],
        "createdAt": row.get("created_at"),
        "lastUsedAt": row.get("last_used_at"),
        "expiresAt": row.get("expires_at"),
        "revokedAt": row.get("revoked_at"),
    }


def profile_api_access_payload(conn, actor: dict[str, Any]) -> dict[str, Any]:
    permissions = set(actor.get("permissions") or [])
    if actor.get("role") == "owner":
        permissions.update(permission_key_catalog(conn))
    manageable = any(
        key in permissions
        for key in ("api.tokens.manage", "api.read", "api.write", "mcp.use")
    ) or bool({key for key in permissions if key.startswith("mcp.tool.")})
    tokens: list[dict[str, Any]] = []
    if table_exists(conn, "api_access_tokens") and actor.get("id"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, name, scopes, permission_keys, created_at, last_used_at, expires_at, revoked_at
                FROM api_access_tokens
                WHERE user_id=%s
                ORDER BY revoked_at NULLS FIRST, created_at DESC
                """,
                (actor["id"],),
            )
            tokens = [api_access_token_row(row) for row in cur.fetchall()]
    return {
        "available": table_exists(conn, "api_access_tokens"),
        "manageable": manageable,
        "tokens": tokens,
        "allowedPermissions": sorted(
            key for key in permissions
            if key.startswith("api.") or key == "mcp.use" or key.startswith("mcp.tool.")
        ),
        "mcpTools": [
            {"name": tool, "permission": f"mcp.tool.{tool}"}
            for tool in MCP_TOOL_NAMES
        ],
    }


def normalize_api_token_permissions(conn, actor: dict[str, Any], raw_values: Any) -> list[str]:
    if raw_values in (None, ""):
        raw_values = []
    if not isinstance(raw_values, list):
        raise NextApiError("permissionKeys must be an array", 400)
    known = permission_key_catalog(conn)
    actor_permissions = set(actor.get("permissions") or [])
    if actor.get("role") == "owner":
        actor_permissions.update(known)
    normalized: list[str] = []
    for item in raw_values:
        key = clean_text(item)
        if not key:
            continue
        if key not in known:
            raise NextApiError(f"Unknown permission: {key}", 400)
        if not (key.startswith("api.") or key == "mcp.use" or key.startswith("mcp.tool.")):
            raise NextApiError(f"Permission is not valid for API tokens: {key}", 400)
        if key not in actor_permissions:
            raise NextApiError(f"You cannot grant API token permission: {key}", 403)
        if key not in normalized:
            normalized.append(key)
    if not normalized:
        defaults = [
            key
            for key in ("api.read", "mcp.use", "mcp.tool.search_collection", "mcp.tool.get_collection_stats", "mcp.tool.get_movie_details")
            if key in actor_permissions
        ]
        normalized = defaults
    if not normalized:
        raise NextApiError("No API or MCP token permissions are available for this user", 403)
    return normalized


def api_token_scopes_for_permissions(permission_keys: list[str]) -> list[str]:
    scopes: list[str] = []
    if "api.read" in permission_keys:
        scopes.append("read")
    if "api.write" in permission_keys:
        scopes.append("write")
    if "mcp.use" in permission_keys or any(key.startswith("mcp.tool.") for key in permission_keys):
        scopes.append("mcp")
    return scopes


def require_next_admin_user(conn) -> dict[str, Any]:
    if not next_auth_effective_enabled(conn, table_exists):
        return {"id": None, "username": "system", "role": "owner"}
    user = next_auth_current_user(conn)
    if not user:
        raise NextApiError("Unauthorized", 401)
    role = next_user_primary_role(conn, user["id"])
    if role not in {"owner", "admin"}:
        raise NextApiError("Admin access required", 403)
    user["role"] = role
    return user


def require_next_authenticated_user(conn) -> dict[str, Any]:
    if not next_auth_effective_enabled(conn, table_exists):
        return {"id": None, "username": "system", "role": "owner", "permissions": ["*"]}
    user = next_auth_current_user(conn)
    if not user:
        raise NextApiError("Unauthorized", 401)
    user["role"] = next_user_primary_role(conn, user["id"])
    user["permissions"] = sorted(next_user_permission_keys(conn, user["id"]))
    return user


def next_user_permission_keys(conn, user_id: UUID | str) -> set[str]:
    if not table_exists(conn, "user_roles") or not table_exists(conn, "role_permissions"):
        return set()
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT DISTINCT rp.permission_key
            FROM user_roles ur
            JOIN role_permissions rp ON rp.role_id = ur.role_id
            WHERE ur.user_id=%s
            """,
            (user_id,),
        )
        return {str(row["permission_key"]) for row in cur.fetchall()}


def actor_api_token_permission_keys(actor: dict[str, Any]) -> set[str] | None:
    token = actor.get("apiToken") or actor.get("api_token")
    if not isinstance(token, dict):
        return None
    return {str(item) for item in (token.get("permissionKeys") or token.get("permission_keys") or [])}


def actor_token_allows_permission(actor: dict[str, Any], permission_key: str) -> bool:
    token_permissions = actor_api_token_permission_keys(actor)
    if token_permissions is None:
        return True
    return "*" in token_permissions or permission_key in token_permissions


def actor_token_allows_any_permission(actor: dict[str, Any], permission_keys: tuple[str, ...]) -> bool:
    token_permissions = actor_api_token_permission_keys(actor)
    if token_permissions is None:
        return True
    return "*" in token_permissions or bool(token_permissions.intersection(permission_keys))


def require_next_permission(conn, permission_key: str) -> dict[str, Any]:
    if not next_auth_effective_enabled(conn, table_exists):
        return {
            "id": None,
            "username": "system",
            "role": "owner",
            "permissions": ["*"],
        }
    user = next_auth_current_user(conn)
    if not user:
        raise NextApiError("Unauthorized", 401)
    role = next_user_primary_role(conn, user["id"])
    permissions = next_user_permission_keys(conn, user["id"])
    if role != "owner" and permission_key not in permissions:
        raise NextApiError(f"Permission required: {permission_key}", 403)
    if not actor_token_allows_permission(user, permission_key):
        raise NextApiError(f"API token permission required: {permission_key}", 403)
    user["role"] = role
    user["permissions"] = sorted(permissions)
    return user


def require_any_next_permission(conn, permission_keys: tuple[str, ...]) -> dict[str, Any]:
    if not next_auth_effective_enabled(conn, table_exists):
        return {
            "id": None,
            "username": "system",
            "role": "owner",
            "permissions": ["*"],
        }
    user = next_auth_current_user(conn)
    if not user:
        raise NextApiError("Unauthorized", 401)
    role = next_user_primary_role(conn, user["id"])
    permissions = next_user_permission_keys(conn, user["id"])
    if role != "owner" and not permissions.intersection(permission_keys):
        raise NextApiError(f"One of these permissions is required: {', '.join(permission_keys)}", 403)
    if not actor_token_allows_any_permission(user, permission_keys):
        raise NextApiError(f"API token requires one of these permissions: {', '.join(permission_keys)}", 403)
    user["role"] = role
    user["permissions"] = sorted(permissions)
    return user


