def plugin_category_set(plugin: dict[str, Any]) -> set[str]:
    manifest = plugin.get("manifest") or {}
    categories = plugin.get("categories") or manifest.get("categories") or []
    return {str(item) for item in categories}


def plugin_action_permissions(plugin: dict[str, Any], entrypoint: str = "") -> tuple[str, ...]:
    categories = plugin_category_set(plugin)
    if {"mcp", "api", "system"}.intersection(categories):
        return ("mcp.use", "api.read", "api.write", "api.tokens.manage", "admin.view_settings")
    if entrypoint == "sync_library":
        return ("digital_sources.sync", "digital_sources.manage")
    if entrypoint == "sync_personal_lists":
        return ("watchlist.manage",)
    if entrypoint in {"discover_library", "playback_deeplink"}:
        return ("digital_sources.view", "digital_sources.connect", "digital_sources.manage")
    if entrypoint in {"inspect_source", "plan_import", "import_source"}:
        return ("collection.import", "admin.restore_functional")
    if entrypoint in {"receive_metadata", "describe_payload", "activity_summary"}:
        return ("metadata.manage_receivers", "metadata.manage_plugins")
    if entrypoint == "health_check":
        permissions = ["metadata.view_plugin_health", "metadata.manage_plugins"]
        if "digital_media_source" in categories:
            permissions.extend(["digital_sources.view", "digital_sources.connect", "digital_sources.manage"])
        if "personal_list_source" in categories:
            permissions.extend(["watchlist.manage", "admin.view_settings"])
        if "import_source" in categories:
            permissions.extend(["collection.import", "admin.restore_functional"])
        return tuple(dict.fromkeys(permissions))
    if "import_source" in categories:
        return ("collection.import", "admin.restore_functional")
    if "digital_media_source" in categories:
        return ("digital_sources.view", "digital_sources.connect", "digital_sources.sync", "digital_sources.manage")
    if "personal_list_source" in categories:
        return ("watchlist.manage",)
    return (
        "metadata.search",
        "metadata.refresh_one",
        "metadata.refresh_bulk",
        "metadata.manage_plugins",
    )


def plugin_manage_permissions(plugin: dict[str, Any]) -> tuple[str, ...]:
    categories = plugin_category_set(plugin)
    permissions: list[str] = []
    if {"mcp", "api", "system"}.intersection(categories):
        permissions.extend(["mcp.use", "api.tokens.manage", "admin.view_settings"])
    if {"metadata_source", "metadata_receiver"}.intersection(categories):
        permissions.extend(["metadata.manage_plugins", "metadata.manage_plugin_settings"])
    if "metadata_receiver" in categories:
        permissions.append("metadata.manage_receivers")
    if "digital_media_source" in categories:
        permissions.extend(["digital_sources.connect", "digital_sources.manage"])
    if "personal_list_source" in categories:
        permissions.append("watchlist.manage")
    if "import_source" in categories:
        permissions.append("collection.import")
    return tuple(dict.fromkeys(permissions or list(PLUGIN_REGISTRY_MANAGE_PERMISSIONS)))


def require_plugin_action_permission(conn, plugin: dict[str, Any], entrypoint: str = "") -> dict[str, Any]:
    return require_any_next_permission(conn, plugin_action_permissions(plugin, entrypoint))


def require_plugin_delete_permission(conn, plugin: dict[str, Any]) -> dict[str, Any]:
    manifest = plugin.get("manifest") or {}
    if manifest.get("systemPlugin") or manifest.get("deletable") is False:
        raise NextApiError("System plugins cannot be deleted", 400)
    actor = require_any_next_permission(conn, ("plugins.delete",))
    if actor.get("role") == "owner":
        return actor
    permissions = set(actor.get("permissions") or [])
    if not permissions.intersection(plugin_manage_permissions(plugin)):
        required = ", ".join(("plugins.delete", *plugin_manage_permissions(plugin)))
        raise NextApiError(f"One of these permissions is required: {required}", 403)
    return actor


def plugin_archive_filename(plugin: dict[str, Any]) -> str:
    manifest = plugin.get("manifest") or {}
    name = str(plugin.get("id") or manifest.get("id") or plugin.get("name") or "plugin").strip()
    version = str(plugin.get("version") or manifest.get("version") or "0.0.0").strip()
    safe_name = re.sub(r"[^A-Za-z0-9._-]+", "_", name).strip("._-") or "plugin"
    safe_version = re.sub(r"[^A-Za-z0-9._-]+", "_", version).strip("._-") or "0.0.0"
    return f"{safe_name}_{safe_version}.zip"


def write_plugin_archive(plugin: dict[str, Any], destination: Path) -> None:
    manifest = plugin.get("manifest") or {}
    if manifest.get("systemPlugin") or manifest.get("deletable") is False:
        raise NextApiError("System plugins cannot be exported", 400)
    plugin_id = str(plugin.get("id") or "").strip()
    source_path = Path(str(plugin.get("sourcePath") or ""))
    if not plugin_id or not source_path.exists() or not source_path.is_dir():
        raise NextApiError("Plugin source directory is not available", 404)
    with zipfile.ZipFile(destination, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for path in sorted(source_path.rglob("*")):
            if path.is_dir():
                continue
            if "__pycache__" in path.parts or path.suffix == ".pyc" or path.name == ".DS_Store":
                continue
            archive.write(path, Path(plugin_id) / path.relative_to(source_path))


def safe_extract_plugin_zip(upload_path: Path, destination_dir: Path) -> None:
    destination = destination_dir.resolve()
    with zipfile.ZipFile(upload_path) as archive:
        for member in archive.infolist():
            member_path = Path(member.filename)
            if member_path.is_absolute() or ".." in member_path.parts:
                raise NextApiError("Plugin ZIP contains unsafe paths", 400)
            target = (destination / member.filename).resolve()
            if destination != target and destination not in target.parents:
                raise NextApiError("Plugin ZIP contains unsafe paths", 400)
        archive.extractall(destination)


def uploaded_plugin_file_path(destination_dir: Path) -> Path:
    upload = request.files.get("file") or request.files.get("plugin")
    if not upload or not upload.filename:
        raise NextApiError("Upload a plugin ZIP as multipart field 'file'", 400)
    if not upload.filename.lower().endswith(".zip"):
        raise NextApiError("Plugin upload must be a .zip file", 400)
    destination_dir.mkdir(parents=True, exist_ok=True)
    target = destination_dir / f"{uuid.uuid4()}.zip"
    upload.save(target)
    return target


def locate_plugin_root(extracted_dir: Path) -> Path:
    direct_manifest = extracted_dir / "manifest.json"
    if direct_manifest.exists():
        return extracted_dir
    candidates = [item for item in extracted_dir.iterdir() if item.is_dir() and (item / "manifest.json").exists()]
    if len(candidates) == 1:
        return candidates[0]
    raise NextApiError("Plugin ZIP must contain exactly one plugin manifest.json", 400)


def validate_import_plugin_root(plugin_root: Path) -> dict[str, Any]:
    manifest_path = plugin_root / "manifest.json"
    plugin_module = plugin_root / "plugin.py"
    if not manifest_path.exists():
        raise NextApiError("Plugin manifest.json is missing", 400)
    if not plugin_module.exists():
        raise NextApiError("Plugin runtime plugin.py is missing", 400)
    try:
        manifest = json_lib.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json_lib.JSONDecodeError) as exc:
        raise NextApiError("Plugin manifest.json is invalid", 400) from exc
    if not isinstance(manifest, dict):
        raise NextApiError("Plugin manifest.json must contain an object", 400)
    plugin_id = str(manifest.get("id") or "").strip()
    if not PLUGIN_ID_PATTERN.match(plugin_id):
        raise NextApiError("Plugin manifest contains an invalid id", 400)
    if plugin_id in {"discvault_mcp", "discvault_api"} or manifest.get("systemPlugin"):
        raise NextApiError("System plugin ids are reserved", 400)
    if not str(manifest.get("name") or "").strip():
        raise NextApiError("Plugin manifest must declare a name", 400)
    if not str(manifest.get("version") or "").strip():
        raise NextApiError("Plugin manifest must declare a version", 400)
    try:
        settings_schema_version = int(manifest.get("settingsSchemaVersion") or 1)
    except (TypeError, ValueError) as exc:
        raise NextApiError("Plugin settings schema version is invalid", 400) from exc
    if settings_schema_version > 1:
        raise NextApiError("Plugin settings schema version is not supported", 400)
    try:
        validate_manifest_compatibility(manifest, require_declared=True)
    except ValueError as exc:
        raise NextApiError(str(exc), 400) from exc
    categories = manifest.get("categories")
    kind = str(manifest.get("kind") or "").strip()
    if not isinstance(categories, list):
        categories = [kind] if kind else []
    valid = {"metadata_source", "metadata_receiver", "digital_media_source", "personal_list_source", "import_source"}
    if not {str(item) for item in categories}.intersection(valid):
        raise NextApiError("Plugin manifest must declare a supported category", 400)
    return manifest


def install_plugin_from_root(plugin_root: Path, manifest: dict[str, Any]) -> Path:
    plugin_id = str(manifest["id"]).strip()
    install_base = DEFAULT_PLUGIN_DIR.resolve()
    target = (install_base / plugin_id).resolve()
    if install_base != target and install_base not in target.parents:
        raise NextApiError("Plugin target path is not safe", 400)
    install_base.mkdir(parents=True, exist_ok=True)
    if target.exists():
        shutil.rmtree(target)
    shutil.copytree(plugin_root, target)
    return target


def plugin_source_path_for_delete(plugin: dict[str, Any]) -> Path | None:
    raw_path = str(plugin.get("sourcePath") or "").strip()
    if not raw_path:
        return None
    source_path = Path(raw_path).resolve()
    allowed_roots = [path.resolve() for path in plugin_paths()]
    for root in allowed_roots:
        if source_path == root:
            raise NextApiError("Refusing to delete the plugin root directory", 400)
        if root in source_path.parents:
            return source_path
    raise NextApiError("Plugin source path is outside the configured plugin roots", 400)


def move_plugin_source_to_trash(plugin: dict[str, Any]) -> tuple[Path | None, Path | None, Path | None]:
    source_path = plugin_source_path_for_delete(plugin)
    if not source_path or not source_path.exists():
        return None, None, None
    trash_root = Path(tempfile.mkdtemp(prefix="discvault-plugin-delete-"))
    trash_path = trash_root / source_path.name
    shutil.move(str(source_path), str(trash_path))
    return source_path, trash_path, trash_root


def restore_plugin_source(source_path: Path | None, trash_path: Path | None) -> None:
    if not source_path or not trash_path or not trash_path.exists():
        return
    source_path.parent.mkdir(parents=True, exist_ok=True)
    if source_path.exists():
        return
    shutil.move(str(trash_path), str(source_path))


def delete_plugin_records(conn, plugin_id: str) -> dict[str, int]:
    deleted: dict[str, int] = {}
    with conn.cursor() as cur:
        if table_exists(conn, "metadata_field_provenance"):
            cur.execute("DELETE FROM metadata_field_provenance WHERE plugin_id=%s", (plugin_id,))
            deleted["metadataFieldProvenance"] = cur.rowcount
        if table_exists(conn, "metadata_plugin_settings"):
            cur.execute("DELETE FROM metadata_plugin_settings WHERE plugin_id=%s", (plugin_id,))
            deleted["metadataPluginSettings"] = cur.rowcount
        if table_exists(conn, "metadata_lookup_cache"):
            cur.execute("DELETE FROM metadata_lookup_cache WHERE plugin_id=%s", (plugin_id,))
            deleted["metadataLookupCache"] = cur.rowcount
        if table_exists(conn, "metadata_plugins"):
            cur.execute("DELETE FROM metadata_plugins WHERE id=%s", (plugin_id,))
            deleted["metadataPlugins"] = cur.rowcount
        if table_exists(conn, "plugin_settings"):
            cur.execute("DELETE FROM plugin_settings WHERE plugin_id=%s", (plugin_id,))
            deleted["pluginSettings"] = cur.rowcount
        if table_exists(conn, "plugins"):
            cur.execute("DELETE FROM plugins WHERE id=%s", (plugin_id,))
            deleted["plugins"] = cur.rowcount
    return deleted


def plugin_requires_config_for_entrypoint(plugin: dict[str, Any], config: dict[str, Any], entrypoint: str) -> bool:
    if entrypoint in {"health_check", "discover_library", "playback_deeplink", "describe_payload", "activity_summary"}:
        return False
    if is_movievault_plugin(str(plugin.get("id") or "")):
        return False
    manifest = plugin.get("manifest") or {}
    return bool(plugin.get("requiresSecrets") or manifest.get("requiresSecrets")) and not bool(config.get("secretsConfigured"))


def uploaded_backup_file_path(destination_dir: Path) -> Path:
    upload = request.files.get("file") or request.files.get("backup")
    if not upload or not upload.filename:
        raise NextApiError("Upload a backup ZIP as multipart field 'file'", 400)
    if not upload.filename.lower().endswith(".zip"):
        raise NextApiError("Backup upload must be a .zip file", 400)
    destination_dir.mkdir(parents=True, exist_ok=True)
    target = destination_dir / f"{uuid.uuid4()}.zip"
    upload.save(target)
    return target


def plugin_secret_key(plugin_id: str, secret_name: str) -> str:
    name = str(secret_name or "").strip()
    if not PLUGIN_SECRET_NAME_PATTERN.match(name):
        raise NextApiError(
            "Secret names may only contain letters, numbers, dots, dashes and underscores",
            400,
        )
    return f"plugin_secret:{plugin_id}:{name}"


def plugin_is_metadata(categories: Any) -> bool:
    values = {str(item) for item in (categories or [])}
    return bool({"metadata_source", "metadata_receiver"}.intersection(values))


def plugin_config_payload(settings: Any, secrets_ref: Any) -> dict[str, Any]:
    safe_settings = settings if isinstance(settings, dict) else {}
    refs = secrets_ref if isinstance(secrets_ref, dict) else {}
    safe_refs: dict[str, dict[str, Any]] = {}
    for name, ref in refs.items():
        if not PLUGIN_SECRET_NAME_PATTERN.match(str(name)):
            continue
        key = ref.get("key") if isinstance(ref, dict) else ref
        item: dict[str, Any] = {"configured": True}
        if key:
            item["key"] = str(key)
        safe_refs[str(name)] = item
    return {
        "settings": safe_settings,
        "settingsConfigured": bool(safe_settings),
        "secretNames": sorted(safe_refs),
        "secretsConfigured": bool(safe_refs),
        "secretsRef": safe_refs,
    }


def plugin_config_from_db(conn, plugin_id: str) -> dict[str, Any]:
    if not table_exists(conn, "plugin_settings"):
        return plugin_config_payload({}, {})
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT settings, secrets_ref
            FROM plugin_settings
            WHERE plugin_id=%s
            """,
            (plugin_id,),
        )
        row = cur.fetchone()
    return plugin_config_payload(
        row.get("settings") if row else {},
        row.get("secrets_ref") if row else {},
    )


def plugin_secret_values(conn, config: dict[str, Any]) -> dict[str, Any]:
    refs = config.get("secretsRef") or {}
    keys = [
        str(ref.get("key"))
        for ref in refs.values()
        if isinstance(ref, dict) and ref.get("key")
    ]
    if not keys or not table_exists(conn, "app_settings"):
        return {}
    values: dict[str, Any] = {}
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT key, value
            FROM app_settings
            WHERE key = ANY(%s) AND is_secret = true
            """,
            (keys,),
        )
        rows = cur.fetchall()
    by_key = {row["key"]: row["value"] for row in rows}
    for name, ref in refs.items():
        key = ref.get("key") if isinstance(ref, dict) else None
        if key in by_key:
            values[str(name)] = by_key[key]
    return values


def plugin_execution_context(
    conn,
    plugin: dict[str, Any],
    config: dict[str, Any],
    actor: dict[str, Any] | None = None,
    *,
    ensure_movievault_token: bool = False,
) -> dict[str, Any]:
    manifest = plugin.get("manifest") or {}
    context = {
        "pluginId": plugin.get("id"),
        "pluginName": plugin.get("name"),
        "enabled": bool(plugin.get("enabled")),
        "categories": plugin.get("categories") or manifest.get("categories") or [],
        "capabilities": plugin.get("capabilities") or manifest.get("capabilities") or [],
        "settings": config.get("settings") or {},
        "secrets": plugin_secret_values(conn, config),
        "settingsConfigured": bool(config.get("settingsConfigured")),
        "secretNames": config.get("secretNames") or [],
        "secretsConfigured": bool(config.get("secretsConfigured")),
        "actor": {
            "id": str(actor.get("id")) if actor and actor.get("id") else None,
            "username": actor.get("username") if actor else None,
            "role": actor.get("role") if actor else None,
        },
    }
    return movievault_plugin_context(
        conn,
        str(plugin.get("id") or ""),
        context,
        ensure_token=ensure_movievault_token,
        actor_id=actor.get("id") if actor else None,
    )


def validate_plugin_execution_request(plugin: dict[str, Any], body: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    entrypoint = str(body.get("entrypoint") or "").strip()
    if not entrypoint:
        raise NextApiError("entrypoint is required", 400)
    runtime = plugin.get("runtime") or {}
    entrypoints = runtime.get("entrypoints") or []
    if entrypoint not in entrypoints:
        raise NextApiError(f"Plugin entrypoint is not available: {entrypoint}", 400)
    if entrypoint != "health_check" and not plugin.get("enabled"):
        raise NextApiError("Plugin must be enabled before execution", 409)
    payload = body.get("payload") or {}
    if not isinstance(payload, dict):
        raise NextApiError("payload must be an object", 400)
    return entrypoint, payload


def update_plugin_config(
    conn,
    *,
    plugin_id: str,
    categories: Any,
    actor_id: UUID | str | None,
    settings_provided: bool,
    settings_value: Any,
    secrets_provided: bool,
    secrets_value: Any,
) -> None:
    if not table_exists(conn, "plugin_settings"):
        raise NextApiError("Plugin settings table is not available", 503)
    if settings_provided and not isinstance(settings_value, dict):
        raise NextApiError("settings must be an object", 400)
    if secrets_provided and not isinstance(secrets_value, dict):
        raise NextApiError("secrets must be an object", 400)

    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT settings, secrets_ref
            FROM plugin_settings
            WHERE plugin_id=%s
            """,
            (plugin_id,),
        )
        existing = cur.fetchone()

    settings = dict(existing.get("settings") or {}) if existing else {}
    secrets_ref = dict(existing.get("secrets_ref") or {}) if existing else {}
    if settings_provided:
        settings = dict(settings_value or {})

    with conn.transaction():
        with conn.cursor() as cur:
            if secrets_provided:
                for raw_name, secret_value in secrets_value.items():
                    secret_name = str(raw_name or "").strip()
                    secret_key = plugin_secret_key(plugin_id, secret_name)
                    if secret_value is None or secret_value == "":
                        cur.execute("DELETE FROM app_settings WHERE key=%s", (secret_key,))
                        secrets_ref.pop(secret_name, None)
                        continue
                    if isinstance(secret_value, (dict, list)):
                        raise NextApiError("Secret values must be scalar JSON values", 400)
                    cur.execute(
                        """
                        INSERT INTO app_settings (key, value, is_secret, updated_at, updated_by)
                        VALUES (%s, %s, true, now(), %s)
                        ON CONFLICT (key) DO UPDATE SET
                            value=EXCLUDED.value,
                            is_secret=true,
                            updated_at=now(),
                            updated_by=EXCLUDED.updated_by
                        """,
                        (secret_key, Jsonb(secret_value), actor_id),
                    )
                    secrets_ref[secret_name] = {
                        "key": secret_key,
                        "configured": True,
                    }

            cur.execute(
                """
                INSERT INTO plugin_settings (plugin_id, settings, secrets_ref, updated_at, updated_by)
                VALUES (%s, %s, %s, now(), %s)
                ON CONFLICT (plugin_id) DO UPDATE SET
                    settings=EXCLUDED.settings,
                    secrets_ref=EXCLUDED.secrets_ref,
                    updated_at=now(),
                    updated_by=EXCLUDED.updated_by
                """,
                (plugin_id, Jsonb(settings), Jsonb(secrets_ref), actor_id),
            )

            if plugin_is_metadata(categories) and table_exists(conn, "metadata_plugin_settings"):
                cur.execute(
                    """
                    INSERT INTO metadata_plugin_settings (
                        plugin_id,
                        settings,
                        secrets_ref,
                        updated_at,
                        updated_by
                    )
                    VALUES (%s, %s, %s, now(), %s)
                    ON CONFLICT (plugin_id) DO UPDATE SET
                        settings=EXCLUDED.settings,
                        secrets_ref=EXCLUDED.secrets_ref,
                        updated_at=now(),
                        updated_by=EXCLUDED.updated_by
                    """,
                    (plugin_id, Jsonb(settings), Jsonb(secrets_ref), actor_id),
                )


def client_entity_mapping(
    conn,
    *,
    client_id: str,
    entity_type: str,
    client_entity_id: str | None,
) -> UUID | None:
    if not client_entity_id:
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT entity_id
            FROM client_id_mappings
            WHERE user_id IS NULL
              AND client_id=%s
              AND entity_type=%s
            """,
            (f"{client_id}:{client_entity_id}", entity_type),
        )
        row = cur.fetchone()
    return row["entity_id"] if row else None


def store_client_entity_mapping(
    conn,
    *,
    client_id: str,
    client_entity_id: str | None,
    entity_type: str,
    entity_id: UUID,
    idem_key: str,
) -> None:
    if not client_entity_id:
        return
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO client_id_mappings (
                user_id,
                client_id,
                entity_type,
                entity_id,
                idempotency_key
            )
            VALUES (NULL, %s, %s, %s, %s)
            ON CONFLICT (user_id, client_id, entity_type) DO NOTHING
            """,
            (f"{client_id}:{client_entity_id}", entity_type, entity_id, idem_key),
        )


def movie_payload_fields(payload: dict[str, Any]) -> dict[str, Any]:
    metadata = payload.get("metadata")
    if not isinstance(metadata, dict):
        metadata = {}
    for source, target in (
        ("posterUrl", "poster_url"),
        ("backdropUrl", "backdrop_url"),
        ("poster_url", "poster_url"),
        ("backdrop_url", "backdrop_url"),
    ):
        if payload.get(source):
            metadata[target] = payload[source]
    release_date = storage_optional_date(payload.get("releaseDate") or payload.get("release_date"))
    purchase_date = storage_optional_date(payload.get("purchaseDate") or payload.get("purchase_date"))
    return {
        "barcode": payload.get("barcode"),
        "title": payload.get("title"),
        "sort_title": payload.get("sortTitle") or payload.get("sort_title"),
        "original_title": payload.get("originalTitle") or payload.get("original_title"),
        "year": payload.get("year"),
        "release_date": release_date,
        "format": payload.get("format"),
        "edition": payload.get("edition"),
        "edition_type": payload.get("editionType") or payload.get("edition_type"),
        "country": payload.get("country"),
        "language": payload.get("language"),
        "runtime_minutes": payload.get("runtimeMinutes") or payload.get("runtime_minutes"),
        "overview": payload.get("overview"),
        "notes": payload.get("notes"),
        "rating": payload.get("rating"),
        "purchase_date": purchase_date,
        "purchase_price": payload.get("purchasePrice") or payload.get("purchase_price"),
        "location": payload.get("location"),
        "metadata": metadata,
    }


MOVIE_EDIT_FIELD_LIMITS = {
    "title": 300,
    "sort_title": 300,
    "original_title": 300,
    "year": 40,
    "barcode": 160,
    "format": 80,
    "edition": 160,
    "country": 80,
    "language": 80,
    "location": 160,
    "overview": 5000,
    "notes": 5000,
}


def parse_optional_date(value: Any, field_name: str) -> date | None:
    text = clean_text(value)
    if not text:
        return None
    try:
        return date.fromisoformat(text)
    except ValueError as exc:
        raise NextApiError(f"{field_name} must use YYYY-MM-DD", 400) from exc


def storage_optional_date(value: Any) -> date | None:
    text = clean_text(value)
    if not text or re.fullmatch(r"\d{4}", text):
        return None
    try:
        return date.fromisoformat(text)
    except ValueError:
        return None


def movie_update_payload(body: dict[str, Any], *, existing: dict[str, Any]) -> dict[str, Any]:
    def pick_text(column: str, *aliases: str) -> str | None:
        keys = (column, *aliases)
        if any(key in body for key in keys):
            raw = next(body[key] for key in keys if key in body)
            value = clean_text(raw)
        else:
            value = existing.get(column)
        if value and len(str(value)) > MOVIE_EDIT_FIELD_LIMITS[column]:
            raise NextApiError(f"{column} must be {MOVIE_EDIT_FIELD_LIMITS[column]} characters or fewer", 400)
        return value

    if "releaseDate" in body or "release_date" in body:
        release_date = parse_optional_date(body.get("releaseDate", body.get("release_date")), "releaseDate")
    else:
        release_date = existing.get("release_date")

    title = pick_text("title")
    if not title:
        raise NextApiError("Movie title is required", 400)

    return {
        "title": title,
        "sort_title": pick_text("sort_title", "sortTitle"),
        "original_title": pick_text("original_title", "originalTitle"),
        "year": pick_text("year"),
        "barcode": pick_text("barcode"),
        "release_date": release_date,
        "format": pick_text("format"),
        "edition": pick_text("edition"),
        "country": pick_text("country"),
        "language": pick_text("language"),
        "overview": pick_text("overview"),
        "notes": pick_text("notes"),
        "location": pick_text("location"),
    }


def movie_edit_receiver_proposal(existing: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
    public_fields = (
        "title",
        "original_title",
        "year",
        "barcode",
        "release_date",
        "format",
        "edition",
        "country",
        "language",
        "overview",
    )

    def comparable(value: Any) -> Any:
        if isinstance(value, date):
            return value.isoformat()
        return clean_text(value)

    movie_updates: dict[str, Any] = {}
    metadata_updates: dict[str, Any] = {}
    for field in public_fields:
        old_value = comparable(existing.get(field))
        new_value = comparable(payload.get(field))
        if old_value == new_value:
            continue
        if not new_value:
            continue
        movie_updates[field] = new_value
        if field == "original_title":
            metadata_updates["originalTitle"] = new_value
        elif field == "release_date":
            metadata_updates["releaseDate"] = new_value
        else:
            metadata_updates[field] = new_value
    if not movie_updates and not metadata_updates:
        return {}
    return {
        "movieUpdates": movie_updates,
        "metadataUpdates": metadata_updates,
        "technicalUpdates": {},
        "mediaUpdates": {},
        "identifiers": {},
        "provenance": [
            {
                "pluginId": "discvault_local_edit",
                "sourceLabel": "DiscVault local edit",
                "fields": sorted(set(movie_updates) | set(metadata_updates)),
            }
        ],
    }


