    def metadata_box_set_proposal_key(proposal: dict[str, Any], result: dict[str, Any] | None = None) -> str:
        result = result or {}
        provider = clean_text(
            proposal.get("provider")
            or proposal.get("source")
            or proposal.get("member_source")
            or result.get("pluginId")
            or result.get("provider")
            or result.get("plugin_id")
        ).casefold()
        title = clean_text(proposal.get("title") or proposal.get("name")).casefold()
        discriminator = clean_text(
            proposal.get("barcode")
            or proposal.get("movievault_id")
            or proposal.get("movievaultId")
            or proposal.get("detailUrl")
            or proposal.get("detail_url")
            or proposal.get("sourceUrl")
            or proposal.get("source_url")
        ).casefold()
        return f"{provider}::{title}::{discriminator}"

    def box_set_proposal_members(proposal: dict[str, Any]) -> list[dict[str, Any]]:
        if not isinstance(proposal, dict):
            return []
        for key in ("movies", "members", "boxSetMovies", "box_set_movies", "items", "releases"):
            value = proposal.get(key)
            if not isinstance(value, list):
                continue
            members = [
                item
                for item in value
                if isinstance(item, dict) and clean_text(item.get("title") or item.get("name"))
            ]
            if members:
                return members
        return []

    def metadata_box_set_proposals(metadata_result: dict[str, Any]) -> list[dict[str, Any]]:
        proposals: list[dict[str, Any]] = []
        seen: set[str] = set()
        for result in metadata_result.get("results") or []:
            if not isinstance(result, dict):
                continue
            raw = result.get("raw") if isinstance(result.get("raw"), dict) else {}
            proposal = (
                result.get("boxSetProposal")
                or result.get("box_set_proposal")
                or raw.get("boxSetProposal")
                or raw.get("box_set_proposal")
            )
            if not isinstance(proposal, dict):
                continue
            members = box_set_proposal_members(proposal)
            if len(members) >= 2:
                normalized = dict(proposal)
                normalized["members"] = members
                normalized["movies"] = members
                normalized.setdefault("provider", clean_text(result.get("pluginId") or result.get("provider") or proposal.get("source")))
                key = metadata_box_set_proposal_key(normalized, result)
                if key in seen:
                    continue
                seen.add(key)
                normalized["_proposalKey"] = key
                proposals.append(normalized)
        return proposals

    def metadata_box_set_proposal(metadata_result: dict[str, Any], selected_key: str = "") -> dict[str, Any]:
        proposals = metadata_box_set_proposals(metadata_result)
        selected_key = clean_text(selected_key).casefold()
        if selected_key:
            for proposal in proposals:
                if clean_text(proposal.get("_proposalKey")).casefold() == selected_key:
                    return proposal
        return proposals[0] if proposals else {}

    def metadata_box_set_artwork_value(*values: Any) -> str:
        for value in values:
            if isinstance(value, list):
                image = metadata_box_set_artwork_value(*value)
                if image:
                    return image
                continue
            if isinstance(value, dict):
                media_updates = value.get("mediaUpdates") if isinstance(value.get("mediaUpdates"), dict) else {}
                poster_update = media_updates.get("poster") if isinstance(media_updates.get("poster"), dict) else {}
                plugin_media_source_url = value.get("sourceUrl") if clean_text(value.get("kind")) == "poster" else ""
                image = metadata_box_set_artwork_value(
                    value.get("posterUrl"),
                    value.get("poster_url"),
                    value.get("poster"),
                    value.get("coverUrl"),
                    value.get("cover_url"),
                    value.get("image"),
                    poster_update.get("sourceUrl"),
                    poster_update.get("source_url"),
                    plugin_media_source_url,
                )
                if image:
                    return image
                continue
            image = server_usable_image(value)
            if image:
                return image
        return ""

    def metadata_box_set_artwork_sources(result: dict[str, Any]) -> list[dict[str, Any]]:
        raw = result.get("raw") if isinstance(result.get("raw"), dict) else {}
        sources = [
            result,
            result.get("movie"),
            result.get("details"),
            result.get("release"),
            result.get("boxSetProposal"),
            result.get("box_set_proposal"),
            raw,
            raw.get("movie"),
            raw.get("details"),
            raw.get("release"),
            raw.get("boxSetProposal"),
            raw.get("box_set_proposal"),
        ]
        for key in ("candidates", "items", "matches"):
            value = result.get(key)
            if isinstance(value, list):
                sources.extend(value)
            raw_value = raw.get(key)
            if isinstance(raw_value, list):
                sources.extend(raw_value)
        return [item for item in sources if isinstance(item, dict)]

    def metadata_box_set_artwork_matches(source: dict[str, Any], proposal_title: str, input_title: str) -> bool:
        source_title = clean_text(
            source.get("title")
            or source.get("name")
            or source.get("releaseTitle")
            or source.get("boxSetTitle")
            or source.get("box_set_title")
        ).casefold()
        if not source_title:
            return False
        proposal_title = proposal_title.casefold()
        input_title = input_title.casefold()
        candidates = [item for item in (proposal_title, input_title) if item]
        return any(item in source_title or source_title in item for item in candidates)

    def enrich_box_set_proposal_artwork(
        proposal: dict[str, Any],
        metadata_result: dict[str, Any],
        body: dict[str, Any],
    ) -> dict[str, Any]:
        if not isinstance(proposal, dict):
            return proposal
        enriched = dict(proposal)
        existing_poster = metadata_box_set_artwork_value(
            enriched.get("posterUrl"),
            enriched.get("poster_url"),
            enriched.get("poster"),
            enriched.get("coverUrl"),
            enriched.get("cover_url"),
        )
        existing_backdrop = metadata_box_set_artwork_value(
            enriched.get("backdropUrl"),
            enriched.get("backdrop_url"),
            enriched.get("backdrop"),
        )
        if existing_poster and existing_backdrop:
            return enriched
        proposal_title = clean_text(enriched.get("title") or enriched.get("name"))
        input_title = clean_text(body.get("title") or body.get("query"))
        fallback_poster = ""
        fallback_backdrop = ""
        providers: list[str] = []
        for result in metadata_result.get("results") or []:
            if not isinstance(result, dict):
                continue
            for source in metadata_box_set_artwork_sources(result):
                if not metadata_box_set_artwork_matches(source, proposal_title, input_title):
                    continue
                if not fallback_poster:
                    fallback_poster = metadata_box_set_artwork_value(source)
                    if fallback_poster:
                        providers.append(clean_text(result.get("pluginId") or result.get("provider") or source.get("provider") or source.get("source")))
                if not fallback_backdrop:
                    fallback_backdrop = metadata_box_set_artwork_value(
                        source.get("backdropUrl"),
                        source.get("backdrop_url"),
                        source.get("backdrop"),
                    )
                if (existing_poster or fallback_poster) and (existing_backdrop or fallback_backdrop):
                    break
            if (existing_poster or fallback_poster) and (existing_backdrop or fallback_backdrop):
                break
        if not existing_poster and fallback_poster:
            enriched["posterUrl"] = fallback_poster
            enriched["poster_url"] = fallback_poster
            enriched["poster"] = fallback_poster
        if not existing_backdrop and fallback_backdrop:
            enriched["backdropUrl"] = fallback_backdrop
            enriched["backdrop_url"] = fallback_backdrop
            enriched["backdrop"] = fallback_backdrop
        if providers:
            fallbacks = enriched.get("metadata_plugin_fallbacks") if isinstance(enriched.get("metadata_plugin_fallbacks"), list) else []
            enriched["metadata_plugin_fallbacks"] = [
                *fallbacks,
                {"kind": "box_set_artwork", "providers": [item for item in providers if item]},
            ]
        return enriched

    def synthetic_box_set_member_barcode(box_set_title: str, parent_barcode: str, index: int) -> str:
        base = clean_text(parent_barcode) or clean_text(box_set_title) or "box-set"
        clean = re.sub(r"[^A-Za-z0-9]+", "_", base).strip("_").upper()[:48] or "BOXSET"
        return f"IMPORT-{clean}-BOX-{index:02d}"

    def physical_format_key(value: Any) -> str:
        text = clean_text(value).casefold().replace("-", " ").replace("_", " ").replace("/", " ")
        text = " ".join(text.split())
        if not text:
            return ""
        if "ultra hd" in text or "uhd" in text or "4k" in text:
            return "ultra_hd_blu_ray"
        if "blu ray" in text or "bluray" in text or text == "bd":
            return "blu_ray"
        if text in {"dvd", "dvd video"}:
            return "dvd"
        if "hd dvd" in text or "hddvd" in text:
            return "hd_dvd"
        if "laserdisc" in text or "laser disc" in text:
            return "laserdisc"
        if "svcd" in text or "vcd" in text:
            return "vcd_svcd"
        return text

    def compatible_box_set_member_format(candidate: Any, expected: Any) -> bool:
        candidate_key = physical_format_key(candidate)
        expected_key = physical_format_key(expected)
        return not candidate_key or not expected_key or candidate_key == expected_key

    def box_set_member_identifiers(member: dict[str, Any]) -> dict[str, str]:
        identifiers: dict[str, str] = {}
        tmdb_id = clean_text(member.get("tmdbId") or member.get("tmdb_id"))
        imdb_id = clean_text(member.get("imdbId") or member.get("imdb_id"))
        if tmdb_id:
            identifiers["tmdb"] = tmdb_id
        if imdb_id:
            identifiers["imdb"] = imdb_id
        return identifiers

    def existing_movie_for_box_set_member(conn, member: dict[str, Any]) -> UUID | None:
        barcode = clean_text(member.get("barcode"))
        title = clean_text(member.get("title") or member.get("originalTitle") or member.get("original_title"))
        year = clean_text(member.get("year"))
        with conn.cursor() as cur:
            if barcode:
                cur.execute("SELECT id FROM movies WHERE barcode=%s", (barcode,))
                row = cur.fetchone()
                if row:
                    return row["id"]
            identifiers = box_set_member_identifiers(member)
            if identifiers and table_exists(conn, "movie_identifiers"):
                for provider, identifier in identifiers.items():
                    cur.execute(
                        """
                        SELECT movie_id
                        FROM movie_identifiers
                        WHERE provider_id=%s AND identifier_type='movie_id' AND identifier=%s
                        LIMIT 1
                        """,
                        (provider, identifier),
                    )
                    row = cur.fetchone()
                    if row:
                        return row["movie_id"]
            if title and year:
                cur.execute(
                    """
                    SELECT id
                    FROM movies
                    WHERE lower(COALESCE(sort_title, title, original_title)) = lower(%s)
                      AND COALESCE(year, '') = %s
                    LIMIT 1
                    """,
                    (title, year),
                )
                row = cur.fetchone()
                if row:
                    return row["id"]
        return None

    def normalized_box_set_members_from_body(body: dict[str, Any]) -> list[dict[str, Any]]:
        raw_members = body.get("boxSetMembers") or body.get("box_set_members")
        if not isinstance(raw_members, list):
            return []
        members = []
        for index, item in enumerate(raw_members[:50], start=1):
            if not isinstance(item, dict):
                continue
            if clean_text(item.get("action")).casefold() == "skip":
                continue
            title = clean_text(item.get("title") or item.get("originalTitle") or item.get("original_title"))
            if not title:
                continue
            member = dict(item)
            member["title"] = title
            member["year"] = clean_text(member.get("year"))
            member["format"] = clean_text(member.get("format"))
            member["sortOrder"] = index
            member["memberConfidence"] = clean_text(member.get("memberConfidence") or member.get("member_confidence") or "manual")
            members.append(member)
        return members

    def merge_box_set_member_enrichment(member: dict[str, Any], metadata_result: dict[str, Any], fallback_format: str) -> dict[str, Any]:
        proposal = metadata_result.get("proposal") if isinstance(metadata_result, dict) else {}
        if not isinstance(proposal, dict):
            return member
        movie_updates = proposal.get("movieUpdates") or {}
        metadata_updates = proposal.get("metadataUpdates") or {}
        technical_updates = proposal.get("technicalUpdates") or {}
        media_updates = proposal.get("mediaUpdates") or {}
        identifiers = proposal.get("identifiers") or {}
        enriched = dict(member)

        def fill(target: str, *values: Any, overwrite: bool = False) -> None:
            if not overwrite and enriched.get(target) not in (None, "", [], {}):
                return
            for value in values:
                if value not in (None, "", [], {}):
                    enriched[target] = value
                    return

        discovered_format = (
            movie_updates.get("format")
            or technical_updates.get("format")
            or metadata_updates.get("format")
            or ""
        )
        # Keep imported box-set members on the selected parent edition format.
        # A DVD box-set must not silently receive 4K members from a broad
        # metadata hit; those hits can still fill identifiers and artwork.
        if discovered_format and compatible_box_set_member_format(discovered_format, fallback_format) and (
            not enriched.get("format") or clean_text(enriched.get("format")) == clean_text(fallback_format)
        ):
            enriched["format"] = discovered_format
        if fallback_format and (
            not enriched.get("format") or not compatible_box_set_member_format(enriched.get("format"), fallback_format)
        ):
            enriched["format"] = fallback_format

        fill("overview", movie_updates.get("overview"), metadata_updates.get("overview"), metadata_updates.get("plot"))
        fill("plot", metadata_updates.get("plot"), movie_updates.get("overview"))
        fill("releaseDate", movie_updates.get("release_date"), metadata_updates.get("release_date"))
        fill("release_date", movie_updates.get("release_date"), metadata_updates.get("release_date"))
        fill("runtimeMinutes", movie_updates.get("runtime_minutes"), metadata_updates.get("runtime_minutes"))
        fill("runtime", movie_updates.get("runtime_minutes"), metadata_updates.get("runtime_minutes"))
        fill("genre", metadata_updates.get("genre"))
        fill("director", metadata_updates.get("director"))
        fill("actor", metadata_updates.get("actor"))
        fill("producer", metadata_updates.get("producer"))
        fill("studios", metadata_updates.get("studios"))

        poster_update = media_updates.get("poster") if isinstance(media_updates.get("poster"), dict) else {}
        backdrop_update = media_updates.get("backdrop") if isinstance(media_updates.get("backdrop"), dict) else {}
        poster_url = metadata_updates.get("poster_url") or poster_update.get("sourceUrl")
        backdrop_url = metadata_updates.get("backdrop_url") or backdrop_update.get("sourceUrl")
        fill("poster", poster_url)
        fill("posterUrl", poster_url)
        fill("poster_url", poster_url)
        fill("backdrop", backdrop_url)
        fill("backdropUrl", backdrop_url)
        fill("backdrop_url", backdrop_url)
        fill("backdropUrls", metadata_updates.get("backdrop_urls"))
        fill("backdrop_urls", metadata_updates.get("backdrop_urls"))

        if identifiers.get("tmdb") and not (enriched.get("tmdbId") or enriched.get("tmdb_id")):
            enriched["tmdbId"] = str(identifiers["tmdb"])
            enriched["tmdb_id"] = str(identifiers["tmdb"])
        if identifiers.get("imdb") and not (enriched.get("imdbId") or enriched.get("imdb_id")):
            enriched["imdbId"] = str(identifiers["imdb"])
            enriched["imdb_id"] = str(identifiers["imdb"])

        if technical_updates:
            enriched["technicalSpecs"] = {**(enriched.get("technicalSpecs") or {}), **technical_updates}
        source_summary = [
            item
            for item in (metadata_result.get("sourceSummary") or [])
            if item.get("state") in {"applied", "hit"}
        ]
        if source_summary:
            enriched["metadataPluginEnrichment"] = [
                {
                    "pluginId": item.get("pluginId"),
                    "state": item.get("state"),
                    "reason": item.get("reason"),
                }
                for item in source_summary
            ]
        return {key: value for key, value in enriched.items() if value not in (None, "", [], {})}

    def enrich_box_set_member_for_import(
        conn,
        member: dict[str, Any],
        *,
        proposal: dict[str, Any],
        body: dict[str, Any],
        actor: dict[str, Any],
        fallback_format: str,
    ) -> dict[str, Any]:
        title = clean_text(member.get("title") or member.get("originalTitle") or member.get("original_title"))
        if not title and not (member.get("tmdbId") or member.get("tmdb_id") or member.get("imdbId") or member.get("imdb_id")):
            return member
        lookup_payload = {
            "title": title,
            "year": clean_text(member.get("year")),
            "tmdbId": clean_text(member.get("tmdbId") or member.get("tmdb_id")),
            "imdbId": clean_text(member.get("imdbId") or member.get("imdb_id")),
            "barcode": clean_text(member.get("barcode")),
            "format": clean_text(member.get("format") or fallback_format),
            "parentBoxSets": [
                {
                    "title": clean_text(proposal.get("title") or proposal.get("name")),
                    "barcode": clean_text(proposal.get("barcode") or body.get("barcode")),
                    "format": clean_text(body.get("format") or proposal.get("format") or fallback_format),
                }
            ],
        }
        try:
            metadata_result = lookup_metadata_sources(conn, lookup_payload, actor)
        except Exception as exc:
            return {
                **member,
                "metadataPluginWarning": str(exc),
            }
        return merge_box_set_member_enrichment(member, metadata_result, fallback_format)

    def box_set_member_import_payload(member: dict[str, Any], *, box_set_title: str, fallback_format: str, barcode: str) -> dict[str, Any]:
        metadata = {}
        for key in (
            "genre",
            "director",
            "actor",
            "producer",
            "studios",
            "poster_url",
            "posterUrl",
            "backdrop_url",
            "backdropUrl",
            "backdrop_urls",
            "backdropUrls",
            "identifiedBy",
            "memberConfidence",
            "metadataPluginEnrichment",
            "metadataPluginWarning",
            "sourceRef",
        ):
            value = member.get(key)
            if value not in (None, "", [], {}):
                metadata[key] = value
        metadata["box_set"] = box_set_title
        return {
            "barcode": barcode,
            "title": clean_text(member.get("title")),
            "originalTitle": clean_text(member.get("originalTitle") or member.get("original_title")),
            "year": clean_text(member.get("year")),
            "releaseDate": clean_text(member.get("releaseDate") or member.get("release_date")),
            "format": clean_text(member.get("format")) or fallback_format,
            "overview": clean_text(member.get("overview") or member.get("plot")),
            "runtimeMinutes": member.get("runtimeMinutes") or member.get("runtime_minutes") or member.get("runtime"),
            "country": clean_text(member.get("country")),
            "language": clean_text(member.get("language")),
            "rating": clean_text(member.get("rating")),
            "metadata": metadata,
        }

    def box_set_member_metadata_proposal(member: dict[str, Any]) -> dict[str, Any]:
        movie_updates = {}
        member_format = clean_text(member.get("format"))
        if member_format:
            movie_updates["format"] = member_format
        metadata_updates = {}
        for source, target in (
            ("genre", "genre"),
            ("director", "director"),
            ("actor", "actor"),
            ("producer", "producer"),
            ("studios", "studios"),
            ("posterUrl", "poster_url"),
            ("poster_url", "poster_url"),
            ("backdropUrl", "backdrop_url"),
            ("backdrop_url", "backdrop_url"),
            ("backdropUrls", "backdrop_urls"),
            ("backdrop_urls", "backdrop_urls"),
        ):
            value = member.get(source)
            if value not in (None, "", [], {}):
                metadata_updates[target] = value
        media_updates = {}
        poster_url = clean_text(member.get("posterUrl") or member.get("poster_url") or member.get("poster"))
        backdrop_url = clean_text(member.get("backdropUrl") or member.get("backdrop_url") or member.get("backdrop"))
        if poster_url:
            media_updates["poster"] = {
                "kind": "poster",
                "sourceUrl": poster_url,
                "options": [poster_url],
                "providerId": "movievault",
                "sourceLabel": "MovieVault",
                "sourceRef": clean_text(member.get("sourceRef")),
            }
        if backdrop_url:
            media_updates["backdrop"] = {
                "kind": "backdrop",
                "sourceUrl": backdrop_url,
                "options": [backdrop_url],
                "providerId": "movievault",
                "sourceLabel": "MovieVault",
                "sourceRef": clean_text(member.get("sourceRef")),
            }
        raw_technical = member.get("technicalSpecs") if isinstance(member.get("technicalSpecs"), dict) else {}
        technical_updates = {}
        for source, target in (
            ("hdr", "hdr"),
            ("packaging", "packaging"),
            ("screen_ratios", "screen_ratios"),
            ("screenRatios", "screen_ratios"),
            ("audio_tracks", "audio_tracks"),
            ("audioTracks", "audio_tracks"),
            ("subtitles", "subtitles"),
            ("regions", "regions"),
            ("content_ratings", "content_ratings"),
            ("contentRatings", "content_ratings"),
        ):
            value = member.get(source)
            if value in (None, "", [], {}):
                value = raw_technical.get(source)
            if value not in (None, "", [], {}):
                technical_updates[target] = value
        return {
            "movieUpdates": movie_updates,
            "metadataUpdates": metadata_updates,
            "technicalUpdates": technical_updates,
            "identifiers": box_set_member_identifiers(member),
            "mediaUpdates": media_updates,
        }

    def import_box_set_proposal(conn, proposal: dict[str, Any], body: dict[str, Any], actor: dict[str, Any]) -> dict[str, Any]:
        if not table_exists(conn, "containers") or not table_exists(conn, "container_movies"):
            raise NextApiError("Container tables are not available", 503)
        title = clean_text(proposal.get("title") or proposal.get("name") or body.get("title"))
        override_members = normalized_box_set_members_from_body(body)
        proposal_members = box_set_proposal_members(proposal)
        members = override_members or proposal_members
        if not title or len(members) < 2:
            raise NextApiError("Box-set proposal requires a title and at least two members.", 422)
        fallback_format = clean_text(body.get("format") or proposal.get("format") or proposal.get("mediaType") or proposal.get("media_type"))
        if fallback_format:
            for member in members:
                if not clean_text(member.get("format")) or not compatible_box_set_member_format(member.get("format"), fallback_format):
                    member["format"] = fallback_format
        barcode = clean_text(proposal.get("barcode") or body.get("barcode"))
        provider_label = clean_text(
            proposal.get("provider")
            or proposal.get("source")
            or proposal.get("member_source")
            or "metadata plugin"
        )
        member_source = clean_text(proposal.get("memberSource") or proposal.get("member_source") or provider_label)
        member_confidence = clean_text(proposal.get("memberConfidence") or proposal.get("member_confidence"))
        container_uuid = uuid.uuid4()
        container_public_id = f"import-box-set-{container_uuid.hex[:12]}"
        container_metadata = {
            "source": provider_label,
            "import_source": "plugin_box_set",
            "provider": provider_label,
            "box_set_proposal_key": proposal.get("_proposalKey"),
            "movievault_id": proposal.get("movievault_id"),
            "member_source": member_source,
            "member_confidence": member_confidence,
            "metadata_plugin_fallbacks": proposal.get("metadata_plugin_fallbacks") or [],
            "poster_url": proposal.get("poster_url") or proposal.get("poster"),
            "backdrop_url": proposal.get("backdrop_url") or proposal.get("backdrop"),
            "backdrop_urls": proposal.get("backdrop_urls") or proposal.get("backdropUrls") or [],
        }
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO containers (
                    id, public_id, container_type, title, barcode, badge_label, year, description, metadata, created_at, updated_at
                )
                VALUES (%s, %s, 'box_set', %s, %s, NULL, %s, %s, %s, now(), now())
                """,
                (
                    container_uuid,
                    container_public_id,
                    title,
                    barcode or None,
                    clean_text(proposal.get("year") or proposal.get("year_range")),
                    clean_text(proposal.get("description")),
                    Jsonb(json_ready(container_metadata)),
                ),
            )

        imported_movies = []
        applied_members = []
        metadata_refresh_movie_ids: list[str] = []
        decision_counts = {"created": 0, "linkedExisting": 0, "skipped": 0, "metadataRefreshQueued": 0}
        for index, member in enumerate(members[:50], start=1):
            original_confidence = clean_text(member.get("memberConfidence") or member.get("member_confidence") or member_confidence)
            member = enrich_box_set_member_for_import(
                conn,
                member,
                proposal=proposal,
                body=body,
                actor=actor,
                fallback_format=fallback_format,
            )
            existing_id = existing_movie_for_box_set_member(conn, member)
            member_barcode = clean_text(member.get("barcode")) or synthetic_box_set_member_barcode(title, barcode, index)
            payload = box_set_member_import_payload(
                member,
                box_set_title=title,
                fallback_format=fallback_format,
                barcode=member_barcode,
            )
            if existing_id:
                movie_id = existing_id
                import_action = "linked_existing"
                decision_counts["linkedExisting"] += 1
            else:
                mutation_id = f"import-box-set-member-{uuid.uuid4()}"
                upsert = apply_movie_upsert(
                    conn,
                    client_id="next-import-center",
                    idem_key=f"next-import-center:{mutation_id}",
                    mutation={
                        "clientMutationId": mutation_id,
                        "entityType": "movie",
                        "operation": "upsert",
                        "payload": payload,
                    },
                )
                movie_id = upsert["entityId"]
                import_action = "created"
                decision_counts["created"] += 1
            applied = apply_metadata_proposal(conn, movie_id, box_set_member_metadata_proposal(member), actor=actor)
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO container_movies (container_id, movie_id, sort_order, created_at)
                    VALUES (%s, %s, %s, now())
                    ON CONFLICT (container_id, movie_id) DO UPDATE SET sort_order=EXCLUDED.sort_order
                    """,
                    (container_uuid, movie_id, index),
                )
            detail = movie_detail_entity(conn, movie_id)
            imported_movies.append(detail.get("movie") if detail else {"id": str(movie_id), "title": payload.get("title")})
            applied_members.append(
                {
                    "movieId": str(movie_id),
                    "title": payload.get("title"),
                    "action": import_action,
                    "confidence": original_confidence,
                    "source": clean_text(member.get("source") or member_source),
                    "applied": applied,
                }
            )
            confidence_key = original_confidence.casefold()
            if confidence_key in {"candidate", "needs_member_confirmation", "needs confirmation", "low"} or not box_set_member_identifiers(member):
                metadata_refresh_movie_ids.append(str(movie_id))

        queued_jobs = []
        if metadata_refresh_movie_ids:
            for movie_id in dict.fromkeys(metadata_refresh_movie_ids):
                queued_jobs.append(
                    create_background_job(
                        conn,
                        job_type=METADATA_REFRESH_JOB_TYPE,
                        payload={
                            "movieId": movie_id,
                            "dryRun": False,
                            "requestedBy": actor_job_payload(actor),
                            "reason": "box_set_member_confirmation",
                            "source": provider_label,
                        },
                    )
                )
            decision_counts["metadataRefreshQueued"] = len(queued_jobs)

        audit_event(
            conn,
            event_type="box_set.imported",
            category="import",
            actor=actor,
            target_type="container",
            target_id=container_uuid,
            summary=f"Imported box-set {title}",
            metadata={
                "barcode": barcode,
                "members": len(imported_movies),
                "source": provider_label,
                "memberSource": member_source,
                "memberConfidence": member_confidence,
                "proposalKey": proposal.get("_proposalKey"),
                "decisionCounts": decision_counts,
                "memberOverridesApplied": bool(override_members),
                "appliedMembers": applied_members,
                "queuedMetadataRefreshJobs": [str(job.get("id")) for job in queued_jobs],
            },
        )
        return {
            "container": container_detail_entity(conn, container_uuid),
            "movies": imported_movies,
            "appliedMembers": applied_members,
            "queuedMetadataRefreshJobs": queued_jobs,
            "decisionCounts": decision_counts,
        }

    def metadata_import_candidate(metadata_result: dict[str, Any]) -> dict[str, Any]:
        def as_list(value: Any) -> list[Any]:
            return value if isinstance(value, list) else []

        def candidate_values(result: dict[str, Any]) -> list[dict[str, Any]]:
            raw = result.get("raw") if isinstance(result.get("raw"), dict) else {}
            values = [
                result,
                result.get("movie"),
                result.get("details"),
                result.get("release"),
                raw,
                raw.get("movie"),
                raw.get("details"),
                raw.get("release"),
            ]
            values.extend(as_list(result.get("candidates")))
            values.extend(as_list(raw.get("candidates")))
            values.extend(as_list(raw.get("items")))
            return [item for item in values if isinstance(item, dict)]

        def first_value(result: dict[str, Any], *keys: str) -> str:
            for source in candidate_values(result):
                for key in keys:
                    value = clean_text(source.get(key))
                    if value:
                        return value
            return ""

        for result in metadata_result.get("results") or []:
            if not isinstance(result, dict):
                continue
            movie_updates = result.get("movieUpdates") if isinstance(result.get("movieUpdates"), dict) else {}
            metadata_updates = result.get("metadataUpdates") if isinstance(result.get("metadataUpdates"), dict) else {}
            media_updates = result.get("mediaUpdates") if isinstance(result.get("mediaUpdates"), dict) else {}
            poster_update = media_updates.get("poster") if isinstance(media_updates.get("poster"), dict) else {}
            title = (
                clean_text(movie_updates.get("title") or movie_updates.get("original_title"))
                or first_value(result, "title", "originalTitle", "original_title", "name", "movieTitle", "movie_title")
            )
            if not title:
                continue
            return {
                "title": title,
                "year": clean_text(movie_updates.get("year")) or first_value(result, "year", "releaseYear", "release_year", "movieYear", "movie_year"),
                "format": clean_text(movie_updates.get("format")) or first_value(result, "format", "mediaFormat", "media_format", "releaseFormat", "release_format"),
                "poster_url": (
                    clean_text(metadata_updates.get("poster_url") or metadata_updates.get("posterUrl") or metadata_updates.get("poster"))
                    or clean_text(poster_update.get("sourceUrl") or poster_update.get("source_url"))
                    or first_value(result, "posterUrl", "poster_url", "poster", "coverUrl", "cover_url")
                ),
                "overview": clean_text(movie_updates.get("overview") or metadata_updates.get("overview") or metadata_updates.get("plot"))
                or first_value(result, "overview", "plot", "description"),
            }
        return {}

    def metadata_lookup_audit_payload(body: dict[str, Any], result: dict[str, Any]) -> dict[str, Any]:
        query = result.get("query") if isinstance(result.get("query"), dict) else {}
        proposal = result.get("proposal") if isinstance(result.get("proposal"), dict) else {}
        executions = result.get("executions") if isinstance(result.get("executions"), list) else []
        results = result.get("results") if isinstance(result.get("results"), list) else []
        box_set_proposals = metadata_box_set_proposals(result)
        return {
            "query": {
                "title": query.get("title") or clean_text(body.get("title") or body.get("query")),
                "year": query.get("year") or clean_text(body.get("year")),
                "barcode": query.get("externalBarcode") or query.get("barcode") or clean_text(body.get("barcode")),
                "format": query.get("format") or clean_text(body.get("format") or body.get("mediaFormat")),
                "detectBoxSets": bool(query.get("detectBoxSets") or body.get("detectBoxSets") or body.get("detect_box_sets")),
                "previewMode": bool(query.get("previewMode") or body.get("previewMode") or body.get("preview_mode")),
            },
            "sourceOrder": result.get("sourceOrder") or [],
            "sourceSummary": result.get("sourceSummary") or [],
            "executions": [
                {
                    "pluginId": item.get("pluginId"),
                    "entrypoint": item.get("entrypoint"),
                    "status": item.get("status"),
                    "state": item.get("state"),
                    "resultStatus": item.get("resultStatus"),
                    "candidateCount": item.get("candidateCount"),
                    "elapsedMs": item.get("elapsedMs"),
                    "error": item.get("error"),
                }
                for item in executions
                if isinstance(item, dict)
            ],
            "providerResults": [metadata_result_summary(item) for item in results if isinstance(item, dict)],
            "proposalStats": result.get("proposalStats") or {},
            "acceptedFields": proposal.get("provenance") or [],
            "skippedFields": proposal.get("skipped") or [],
            "boxSetProposals": [
                {
                    "provider": item.get("provider") or item.get("source"),
                    "title": item.get("title") or item.get("name"),
                    "memberCount": len(box_set_proposal_members(item)),
                    "memberConfidence": item.get("memberConfidence") or item.get("member_confidence"),
                    "source": item.get("memberSource") or item.get("member_source") or item.get("source"),
                }
                for item in box_set_proposals
            ],
        }

